def link_spark_paxos(history):
    from ..normalize.allocation_capital import AssetMovement

    cash_prefix = "ethereum:" + HOLDER + ":"
    if cash_prefix + USDC not in history.venue_accounts.values():
        return history
    indexed = {b.identity: b for b in history.batches}
    if len(indexed) != len(history.batches):
        raise ValueError("Duplicate Spark capital transaction")
    if VENUE in history.venue_accounts:
        if history.venue_accounts[VENUE] != ACCOUNT:
            raise ValueError("Spark Paxos boundary already mapped elsewhere")
        if any("ethereum:" + e[0] in indexed for e in EVENTS):
            raise ValueError("Partially applied Spark Paxos history")
        return history
    if not any("ethereum:"+e[0] in indexed for e in EVENTS):
        return history
    groups = defaultdict(list)
    for e in EVENTS:
        groups["ethereum:" + e[0]].append(e)
    horizon = max((b.block for b in history.batches if b.chain == "ethereum"), default=0)
    balance = D(0)
    changed = False
    for identity, events in groups.items():
        b = indexed.get(identity)
        if b is None:
            if events[0][1] <= horizon:
                raise ValueError("Missing Spark Paxos transaction within history")
            continue  # Pinned histories need not extend through the full review.
        if any((b.chain, b.block, b.timestamp) != ("ethereum", e[1], e[2]) for e in events):
            raise ValueError("Spark Paxos event metadata changed")
        paid = sum((D(e[4]) / 10**6 for e in events if e[5]), D(0))
        received = sum((D(e[4]) / 10**6 for e in events if not e[5]), D(0))
        required = {
            cash_prefix + token for token, amount in ((PYUSD, paid), (USDC, received)) if amount
        }
        for account in required:
            if sum(m.account == account for m in b.movements) != 1:
                raise ValueError("Spark Paxos boundary missing normalized cash movement")
        if received:
            cash = next(m for m in b.movements if m.account == cash_prefix + USDC)
            if cash.change != received or cash.external_income:
                raise ValueError("Reviewed Paxos return cash shape changed")
        if balance + paid < received:
            raise ValueError("Spark Paxos return exceeds observed boundary funding")
        movement = AssetMovement(ACCOUNT, balance, paid - received, preserve_basis=True)
        balance += paid - received
        assumption = (b.funding_assumption + " " if b.funding_assumption else "") + POLICY
        indexed[identity] = replace(
            b,
            identity=identity + MARKER,
            movements=(*b.movements, movement),
            funding_assumption=assumption,
        )
        changed = True
    if not changed:
        return history
    return replace(
        history,
        batches=tuple(indexed.values()),
        venue_accounts={**history.venue_accounts, VENUE: ACCOUNT},
        analytics_only_venues=(*history.analytics_only_venues, VENUE),
    )
